WHO = {'column': [('eindeyeben', 126986), ('alphafcyeben', 126986), ('rosehceyeben', 127434), ('einsof', 127434), ('renmalsof', 127434), ('shathisha', 127434), ('mulceeyeben', 127434), ('qum', 0)], 'temple': [('kawei', 127178), ('mulcevi', 128520), ('alphafolhlso', 0), ('mulcecuya', 133163), ('aprieyeben', 136202), ('kawei', 0), ('mulcevi', 0)], 'tower': [('seneecfeocum', 127434), ('eindeeyeben', 0), ('brideeben', 128136), ('alphafocren', 130047), ('mulceceyeben', 130303), ('seneecocuya', 132843), ('alphafocren', 0), ('seneecfeocum', 0)], 'bridge': [('alphafoldmicro', 127880), ('alphafolhlso', 127880), ('alphafoldmicro', 129094), ('alphafoldmicro', 134045), ('alphafolhlso', 134045), ('alphafoldmicro', 137590), ('alphafoldmicro', 0), ('alphafolhlso', 138164)], 'tree': [('renmaeyeben', 127880), ('eindecyeben', 0), ('seneecefools', 128136), ('renmaocren', 0), ('seneeefools', 0), ('renmalsof', 128392), ('renmaocren', 0), ('yavi', 130047)], 'manor': [('qum', 131257), ('psiloceyeben', 131763), ('eindeeyeben', 133477), ('alphafocren', 135506), ('shathisha', 137400), ('seneeefools', 137590), ('renmaeyeben', 138100), ('apriehisha', 138983)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW303(OracleReleaseRuntimeW301):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
